class CircuitBreaker:
    def __init__(self, max_fails=2):
        self.fails, self.max_fails, self.open = 0, max_fails, False
    def call(self, fn):
        if self.open: return 'FALLBACK_CACHED_DATA'
        try: return fn()
        except Exception:
            self.fails += 1
            if self.fails >= self.max_fails: self.open = True
            return 'FAILOVER'
