import time
class SimpleTTLCache:
    def __init__(self, ttl_seconds=10):
        self.ttl, self.cache = ttl_seconds, {}
    def set(self, k, v):
        self.cache[k] = (v, time.time() + self.ttl)
    def get(self, k):
        if k in self.cache and time.time() < self.cache[k][1]:
            return self.cache[k][0]
        return None
