class CircuitBreaker {
    constructor() { this.failures = 0; this.open = false; }
    async exec(fn) {
        if (this.open) return 'CACHED_FALLBACK';
        try { return await fn(); }
        catch {
            if (++this.failures >= 2) this.open = true;
            return 'FAILOVER';
        }
    }
}
