class TTLCache {
    constructor(ttlMs = 1000) { this.cache = new Map(); this.ttl = ttlMs; }
    set(k, v) { this.cache.set(k, { val: v, exp: Date.now() + this.ttl }); }
    get(k) {
        const entry = this.cache.get(k);
        return (entry && entry.exp > Date.now()) ? entry.val : null;
    }
}
