class TaskQueue {
    constructor(limit) { this.limit = limit; this.running = 0; this.q = []; }
    push(task) { this.q.push(task); this.next(); }
    next() {
        if (this.running < this.limit && this.q.length) {
            this.running++;
            this.q.shift()().then(() => { this.running--; this.next(); });
        }
    }
}
console.log('TaskQueue initialized');

